(function(){'use strict';
const C=SN,A=SNArt,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=localStorage}catch{}const db=new C.Store(storage);let s=C.newSession(),teacher=false,learner='1',errors={},saveMessage='Start a session to save your work',noticeTimer=null,pendingImport=null,printMode='report';
const btn=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const src=(id)=>C.sources[id]?`<a href="${C.sources[id][1]}" target="_blank" rel="noopener">${esc(C.sources[id][0])}</a>`:esc(id);
const fieldId=(g,f)=>'field-'+g+'-'+f;
function toast(text){$('#notice').className='notice';$('#notice').textContent=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').textContent='',6500)}
function save(){try{db.save(s);saveMessage='Saved on this device · '+new Date(s.updatedAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});$('#save-status')&&($('#save-status').textContent=saveMessage);return true}catch(e){saveMessage=e.message==='CONFLICT'?'Newer work exists in another tab. Open Sessions to reload or duplicate.':e.message;$('#save-status')&&($('#save-status').textContent=saveMessage);return false}}
function openDialog(title,body,footer=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialoghead"><h2>${esc(title)}</h2>${btn('close','Close','small')}</div><div class="dialogbody">${body}</div>${footer?'<div class="navbottom">'+footer+'</div>':''}`;if(!d.open)d.showModal();}
function summary(message=''){const items=Object.entries(errors);return `<div id="error-summary" class="error-summary" tabindex="-1">${message?'<p>'+esc(message)+'</p>':''}${items.length?'<h3>Let’s check these fields</h3><ul>'+items.map(([k,v])=>`<li><a href="#${esc(k)}">${esc(v)}</a></li>`).join('')+'</ul>':''}</div>`}
function inputHTML(g,f){const id=fieldId(g.id,f.id),k=C.key(g.id,f.id),v=s.inputs[k]||'',err=errors[id],attrs=`id="${id}" data-input="${k}" aria-invalid="${!!err}" ${err?`aria-describedby="${id}-error"`:''}`;let control;
if(f.kind==='select')control=`<select ${attrs}><option value="">Choose…</option>${f.options.map(([value,label])=>`<option value="${esc(value)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
else if(f.kind==='text')control=`<textarea ${attrs} maxlength="600">${esc(v)}</textarea>`;
else control=`<div class="numeric-wrap"><input ${attrs} type="text" inputmode="${['exponent','coefficient','decimal'].includes(f.kind)?'decimal':'text'}" autocomplete="off" spellcheck="false" maxlength="100" value="${esc(v)}">${f.kind==='exponent'||f.id.endsWith('Deviation')?btn('minus','−','minus',`data-target="${id}" aria-label="Toggle minus sign for ${esc(f.label)}"`):''}</div>`;
return `<div class="field ${f.kind==='text'?'wide':''}"><label for="${id}">${esc(f.label)}</label>${control}${err?`<span class="error" id="${id}-error">${esc(err)}</span>`:''}</div>`}
function groupHTML(g){const state=C.status(s,g.id),r=C.raw(s,g.id),o=g.operation;let fields=g.fields;if(g.type==='measurement')fields=fields.filter(f=>f.id.endsWith('Deviation'));if(g.type==='transfer')fields=fields.filter(f=>r.mode==='paper'?['mode','submission'].includes(f.id):f.id!=='submission');const op=!!o;const method=op?fields.filter(f=>!['a','n','unit'].includes(f.id)):[];if(op)fields=fields.filter(f=>['a','n','unit'].includes(f.id));
return `<section class="card ${op?(o.domain==='Microscopic'?'micro':'macro'):''}" id="group-${g.id}"><div class="cardhead"><div><div class="tag">${esc(op?o.domain+' · '+o.op:g.id.replace(/[abAB]$/,''))}</div><h3>${esc(g.title)}</h3><span class="badge ${state}">${esc(state.replaceAll('-',' '))}</span></div>${g.type==='transfer'?'':btn('help','?','help',`data-group="${g.id}" aria-label="Help: ${esc(g.title)}"`)}</div><p>${esc(g.prompt)}</p>${o?'<div class="expression">'+esc(o.expression)+'</div>':''}${g.type==='scale'&&s.track==='B'?'<p class="smallprint muted">Moon diameter: 3.5 × 10⁶ m. Mean Earth–Moon distance: 3.84 × 10⁸ m.</p>':''}${g.type==='measurement'?measurementTargets():''}<div class="fields">${fields.map(f=>inputHTML(g,f)).join('')}</div>${op?`<details><summary>Show my method (optional)</summary><p>Method entries are checked separately; a blank method does not block the final-answer check.</p><div class="fields">${method.map(f=>inputHTML(g,f)).join('')}</div><p>${methodStatus(g.id)}</p></details>`:''}${fields.some(f=>f.id==='a')?`<div class="mathpreview" id="preview-${g.id}">${r.a?esc(r.a)+' × 10<sup>'+esc(r.n)+'</sup>':''}</div>`:''}<div class="checkline">${btn('check','Check work','primary',`data-group="${g.id}"`)}${state==='checked'?'<span class="result">Checked against the supplied model.</span>':state==='bypassed'?'<span class="result">Teacher bypass recorded; outcome stays provisional.</span>':''}</div>${op?'<p class="science-note">'+(o.id==='C04a'||o.id==='C05a'?'Ideal diameter model.':o.id==='C04b'||o.id==='C05b'||o.id==='C07b'?'Use the supplied rounded scientific values.':'Authored science-context example, not an experimental observation.')+'</p>':''}</section>`}
function measurementTargets(){return `<div class="factbox">${C.measurements[s.track].map(([,label,target,tol])=>esc(label)+': '+target+' mm, tolerance ±'+tol+' mm').join('<br>')}<br>Deviation = measured − target. Endpoints count as within tolerance.</div>`}
function countDone(){const gs=C.activeGroups(s);return [gs.filter(g=>g.type==='transfer'?C.submissionOK(s,g.id):C.ok(s,g.id)).length,gs.length]}
function header(){const [done,total]=countDone();return `<header class="masthead"><div class="brand"><div class="brand-icon">10<sup>n</sup></div><div><strong>Powers of Ten</strong><span class="eyebrow">Science + Mathematics · v${C.VERSION}</span></div></div><div class="toolbar"><span id="save-status">${esc(saveMessage)}</span>${btn('save','Save','small')}${btn('export','Export draft','small')}${btn('sessions','Sessions','small')}${btn('print-menu','Print','small')}${btn('guides','Teacher guides','small')}</div></header><nav class="steps" aria-label="Subject dashboard">${[['dashboard','My project'],['science','Science Day'],['math','Mathematics Day']].map(([id,name])=>btn('lesson',name,s.lesson===id?'active':'',`data-lesson="${id}"`)).join('')}${btn('evidence','My evidence and exports')}</nav>${!db.available?'<p class="hint">Storage unavailable. Keep this page open and export your progress before closing.</p>':''}<main id="main" tabindex="-1">${summary()}${s.lesson==='math'?`<div class="sectiontop"><h2>Mathematics Day</h2><span class="badge">${done}/${total} checks · ${Object.keys(C.scienceErrors(s)).length?'Science evidence incomplete':'Science record ready'}</span></div><nav class="toolbar" aria-label="Math tasks">${[[2,'Quantities'],[3,'8 calculations'],[4,'Intended scale'],[6,'Scale audit'],[7,'Exhibit & exits'],[8,'Final record']].map(([id,label])=>btn('math-stage',label,s.currentStage===id?'primary':'',`data-stage="${id}"`)).join('')}</nav><p>Use your labeled model and Science passport. Pair roles alternate Calculator/Checker after each calculation.</p>`:''}`;}
function nav(){if(s.lesson!=='math')return '';return `<div class="navbottom">${btn('lesson','Science evidence','',`data-lesson="science"`)}${s.currentStage<8?btn('next','Check & continue →','primary'):btn('export','Export final record','primary')}</div>`;}
function render(){const bodies={2:notation,3:calculations,4:planning,6:verification,7:gallery,8:publish};$('#app').innerHTML=header()+(s.lesson==='dashboard'?dashboard():s.lesson==='science'?scienceDay():(bodies[s.currentStage]||notation)())+nav()+`</main><footer class="footer"><span>A WILLIAM MCADA PRODUCT · © 2026 William McAda</span><span>App ${C.VERSION} · Content ${C.CONTENT} · Alias-only progress on this device</span></footer>`;}
function commission(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Museum investigation / 01</p><h1>Too small.<br>Too far.<br><em>Make it real.</em></h1><p>A museum needs your help. Repair its scale labels, investigate extraordinary quantities, and build an exhibit visitors can understand.</p><div class="hero-count"><span><b>2</b>size worlds</span><span><b>8</b>calculations</span><span><b>1</b>physical exhibit</span></div></div><div class="hero-art">${A.hero()}</div></section><div class="intro-grid"><section class="panel"><p class="eyebrow">Your exhibit team</p><h2>Begin the investigation</h2><p class="muted">Use aliases, not full names. You’ll work together, then each complete a separate exit response.</p><div class="fields"><div class="field wide"><label for="team">Team alias</label><input id="team" data-meta="teamAlias" maxlength="64" value="${esc(s.teamAlias)}" placeholder="e.g. Team Orion"></div><div class="field"><label for="learner1">Learner 1 alias</label><input id="learner1" data-meta="student1" maxlength="64" value="${esc(s.students[0])}" placeholder="e.g. A1"></div><div class="field"><label for="learner2">Learner 2 alias</label><input id="learner2" data-meta="student2" maxlength="64" value="${esc(s.students[1])}" placeholder="e.g. A2"></div><div class="field"><label for="planner">Start as Planner</label><select id="planner" data-meta="planner"><option value="1" ${s.roles.planner==='1'?'selected':''}>Learner 1</option><option value="2" ${s.roles.planner==='2'?'selected':''}>Learner 2</option></select></div></div><p class="smallprint muted">The other learner checks. Swap at chapter breaks. Scientific-notation operations should already be familiar; this is an application project.</p>${btn('next','Enter the museum →','primary')}</section><aside class="panel soft"><p class="eyebrow">The commission</p><h2>One question.<br>Two ways to build.</h2><p>How can a model represent something too small or too large to experience directly?</p><ol class="stepslist"><li>Investigate notation, units, and both size ranges.</li><li>Build a cell enlargement or Earth–Moon reduction.</li><li>Measure, repair, explain, and publish.</li></ol><p class="smallprint">Two proposed 45-minute lessons. Paper/card, a ruler, tape, markers, and scissors. No microscope or live specimens needed.</p>${btn('import','Resume from a progress file')}</aside></div>`}
function notation(){return `<div class="panel"><h3>Move between worlds</h3><p>Use the complete values, not the exponent alone. These are decade bins for lengths in meters; icons are not drawn at one physical scale.</p><div class="axis-wrap">${A.axis()}</div><details><summary>Accessible magnitude-map description</summary><p>DNA width is in the 10⁻⁹ m decade; a cell diameter in 10⁻⁶; Earth diameter in 10⁷; Earth–Moon distance in 10⁸; Sun diameter in 10⁹; Earth–Sun distance in 10¹¹. Each step multiplies length by ten.</p></details><p class="factbox">Unit reference: 1 m = 100 cm = 1000 mm = 10⁶ µm = 10⁹ nm.</p></div><div class="cards">${C.activeGroups(s,2).map(groupHTML).join('')}</div>`}
function calculations(){return `<div class="panel"><div class="sectiontop"><div><h3>Eight repairs for the museum</h3><p>Work in both worlds. Give a normalized result and its unit. Open optional method fields when they help explain your reasoning.</p></div>${btn('calculator','Coefficient calculator')}</div><p class="smallprint muted">A calculator may help with coefficients. You still choose the exponent, units, and normalized representation. Alternate Calculator and Checker after each task.</p></div><div class="cards">${C.activeGroups(s,3).map(groupHTML).join('')}</div>`}
function planning(){return `<section class="panel"><h3>Derive the intended scale</h3><p>Science supplied the construction targets. Now calculate their intended model:actual ratio. Your actual model may differ; the next task audits what you measured.</p>${passportSummary()}</section>${groupHTML(C.getGroup(s,'C08'+s.track))}`;}
function trackBanner(){return `<div class="track-banner">${A.track(s.track)}<div><p class="eyebrow">${s.track==='A'?'Microscopic enlargement':'Desktop reduction'}</p><h3>${s.track==='A'?'A cell you can hold':'The space between worlds'}</h3><p>Original explanatory diagram. Responsive screen pictures are not physical rulers.</p></div></div>`}
function construction(){return trackBanner()+`<div class="layout"><section class="panel"><h3>Build from supplied Science dimensions</h3><ol class="stepslist">${s.track==='A'?'<li>Draw or use the calibrated guide for a 160 mm diameter paper/card cell.</li><li>Suggest a biconcave disc with a shallow depression. Keep the center intact: no nucleus and no hole.</li><li>Only diameter is part of the scale claim. Any thickness is illustrative.</li><li>Measure your finished model with a ruler; do not copy the planned target into the measurement record.</li>':'<li>Prepare a 20 mm Earth and a Moon with a 5.5 mm construction target. Day 2 will explain the rounded Moon target.</li><li>Mark both circle centers. Join three 200 mm distance segments, or measure 600 mm on a string/strip.</li><li>Put the centers at the endpoints. Edges can extend beyond the strip. The gap is measured center to center.</li><li>A larger Moon symbol must be labeled “not to size scale” and cannot replace the scaled Moon.</li>'}</ol><div class="hint">Print at 100%, not Fit to page. Measure the 50 mm calibration line first. If it differs by more than 0.5 mm, reprint or construct using a ruler.</div><label class="inlinecheck"><input type="checkbox" data-meta="built" ${s.built[s.track]?'checked':''}>We have constructed this physical model and are ready to measure it.</label><div class="field"><label for="builder">Builder (the other learner verifies)</label><select id="builder" data-meta="builder"><option value="1" ${s.roles.builder==='1'?'selected':''}>${esc(s.students[0]||'Learner 1')}</option><option value="2" ${s.roles.builder==='2'?'selected':''}>${esc(s.students[1]||'Learner 2')}</option></select></div><p style="margin-top:18px">${btn('rebuild','Record a rebuild / physical change')}</p></section><aside class="panel"><h3>Materials</h3><p>Paper/card, ruler, pencil, eraser, markers, tape, and child-appropriate scissors.</p>${s.track==='B'?'<p>Also: 60 cm string or joined paper strip.</p>':''}<p class="smallprint muted">A screen picture is not evidence of physical construction. Printer scaling and joins must be checked with a real ruler.</p>${btn('print-direct','Print build sheet','primary',`data-mode="build"`)}<p style="margin-top:12px">${btn('print-direct','Print dimensional templates','',`data-mode="templates"`)}</p></aside></div>`}
function verification(){return `<section class="panel"><h3>Audit the model you actually built</h3><p>Measured model length ÷ actual length, both in mm. Accept exact fractions such as 598/384000000000, or an equivalent model:actual ratio. Deviation = measured − construction target.</p>${passportSummary()}<p>${s.track==='B'?'The exact Moon target is 5.46875 mm; construction rounds it to 5.5 mm. Its inferred ratio need not equal Earth’s exactly. Compare every dimension with its own target and tolerance.':'A 159 mm cell gives k = 19,875 and deviation −1 mm. This is a diameter scale, not a thickness claim.'}</p>${btn('lesson','Correct / review Science evidence','',`data-lesson="science"`)}</section>${groupHTML(C.getGroup(s,'C09'+s.track))}${groupHTML(C.getGroup(s,'C13'+s.track))}<section class="panel"><h3>Physical fit and human review</h3>${measurementTable()}<p>Reported fit: ${C.fit(s)?'within stated tolerances':'outside tolerance or incomplete'}. Inspection: ${esc(C.reviewState(s,'inspection'))}.</p><p>An honest measurement outside tolerance is usable evidence. Keep it and explain the mismatch.</p>${btn('teacher','Record a real inspection')}</section>`;}
function sourceCards(){return `<div class="sourcegrid">${C.objects.map(o=>`<article class="sourcecard">${A.object(o[0])}<h3>${esc(o[1])}</h3><p>${esc(o[2])}</p><b>${esc(o[3])} ${esc(o[4])}</b><p>${src(o[5])}</p><p>Rounded teaching value · diagram</p></article>`).join('')}</div>`}
function placardFields(){const t=s.track,p=C.placardData(s);function sel(f,label,opts){return `<div class="field"><label for="p-${f}">${label}</label><select id="p-${f}" data-input="placard${t}.${f}"><option value="">Choose…</option>${opts.map(([v,l])=>`<option value="${v}" ${p[f]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}return `<section class="panel"><h3>Exhibit labels</h3><p>Missing or inconsistent labels lead to Calibration required. Your other checked mathematics stays intact.</p><div class="fields"><div class="field wide"><label for="p-title">Exhibit title</label><input id="p-title" maxlength="64" data-input="placard${t}.title" value="${esc(p.title)}"></div>${sel('property','What does the model show?',[['diameter','Cell diameter'],['diameter-distance','Earth/Moon diameters and center distance'],['mass','Mass']])}${sel('source','Source credit',[['R2','Histology Guide — cell'],['R3/R4','NASA — Earth and Moon'],['none','No source']])}${sel('scaleConfirmed','Confirm scale label',[['yes','I checked model:actual and direction'],['no','Needs checking']])}</div></section>`}
function gallery(){return `<div class="panel"><h3>The museum’s reference collection</h3><p class="muted">Use supplied rounded values consistently. Drawings explain; they are not new observations. The cell is a teaching exemplar, and orbital distances are mean values.</p>${sourceCards()}</div>${groupHTML(C.getGroup(s,'C10'+s.track))}${groupHTML(C.getGroup(s,'C11match'))}${groupHTML(C.getGroup(s,'C11'+s.track))}${placardFields()}<section class="panel"><div class="sectiontop"><div><p class="eyebrow">Separate evidence</p><h3>Each learner’s exit response</h3><p>Complete your own response without your partner’s help. Revisions are allowed and the first checked response is retained.</p></div>${btn('print-direct','Print answer-free slips','',`data-mode="transfers"`)}</div><div class="tabs">${['1','2'].map(t=>btn('learner',esc(s.students[Number(t)-1]||'Learner '+t),'',`data-learner="${t}" aria-pressed="${learner===t}"`)).join('')}</div>${groupHTML(C.getGroup(s,'C12'+learner))}</section>`}
function measurementTable(){const r=C.raw(s,'C09'+s.track);return `<table><thead><tr><th>Quantity</th><th>Target / tolerance</th><th>Reported measurement</th><th>Deviation (mm)</th></tr></thead><tbody>${C.measurements[s.track].map(([id,label,target,tol])=>`<tr><td>${label}</td><td>${target} ± ${tol} mm</td><td>${esc(r[id]||'Not recorded')} ${esc(r[id+'Unit'])}</td><td>${esc(r[id+'Deviation']||'Not checked')}</td></tr>`).join('')}</tbody></table>`}
function placard(){const p=C.placardData(s),r=C.raw(s,'C08'+s.track),m=C.raw(s,'C09'+s.track),l=C.raw(s,'C10'+s.track),text=C.raw(s,'C11'+s.track),source=s.track==='A'?'R2':'R3/R4';return `<article class="placard"><p class="eyebrow">Too Small, Too Far · ${esc(s.teamAlias)}</p><h3>${esc(p.title||'Untitled exhibit')}</h3><p>${s.track==='A'?'Red blood cell exemplar — supplied diameter 8 × 10⁻⁶ m.':'Earth: 1.28 × 10⁷ m diameter. Moon: 3.5 × 10⁶ m diameter. Mean center distance: 3.84 × 10⁸ m.'}</p><p><strong>Model:actual = ${esc(r.ratioM||'?')}:${esc(r.ratioA||'?')}</strong> · ${esc(r.direction==='enlarge'?'Enlargement':r.direction==='reduce'?'Reduction':'Direction not recorded')}</p><p>Reported ${s.track==='A'?'cell diameter: '+esc(m.cell||'not recorded')+' '+esc(m.cellUnit):'Earth diameter: '+esc(m.earth||'not recorded')+' '+esc(m.earthUnit)+'; Moon: '+esc(m.moon||'not recorded')+' '+esc(m.moonUnit)+'; center distance: '+esc(m.centers||'not recorded')+' '+esc(m.centersUnit)}.</p><p><strong>Model limit:</strong> ${esc(l.comparison||'Not selected')} → ${esc(l.size||'?')} ${l.comparison==='dna'?'mm':'m'}. ${esc(text.interpretation||'Interpretation not submitted.')}</p><p class="smallprint">Source credit entered: ${esc(p.source||'Missing')}. ${p.source===source?source.split('/').map(src).join(' / '):'Check source label.'}</p><p class="smallprint"><strong>${esc(C.outcome(s))}</strong> · Physical inspection: ${esc(C.reviewState(s,'inspection'))} · Interpretation: ${esc(C.reviewState(s,'interpretation'))}${s.imported?' · Imported evidence':''}</p></article>`}
function publish(){const out=C.outcome(s),[done,total]=countDone();return `<section class="verdict"><div class="copy"><p class="eyebrow">Your museum verdict</p><h2>${esc(out)}</h2><p>${out==='Featured exhibit'?'Your calculations, reported measurements, labels, and review records are current. Your exhibit can explain both what its scale preserves and what it leaves out.':out==='Calibration required'?'Your analyzed exhibit needs a repair. Check the measurements, labels, and review notes below; you can print this honest record and return to improve it.':out==='Exhibit ready for review'?'The submitted calculations and model measurements are current. A required human review is still pending.':out.startsWith('Provisional')?'A teacher bypass is active. The report preserves that context and does not treat it as checked mathematics.':'Finish or recheck the required evidence. You can still print a clearly labeled draft and export your work.'}</p></div>${A.outcome(out,s.track)}</section><div class="stats"><div class="stat"><b>${done}/${total}</b><span>Current/submitted checkpoints</span></div><div class="stat"><b>${s.attempts.length}</b><span>Retained checks · not a mastery score</span></div><div class="stat"><b>${C.fit(s)?'Within tolerance':'Check fit'}</b><span>Self-reported physical measurements</span></div></div>${placard()}<div class="cards"><section class="panel"><h3>Review desk</h3>${measurementTable()}<p>Physical inspection: <strong>${C.reviewState(s,'inspection')}</strong></p><p>Interpretation: <strong>${C.reviewState(s,'interpretation')}</strong></p><p>Labels: <strong>${C.labelsOK(s)?'Complete and consistent':'Repair required'}</strong></p>${btn('teacher','Open teacher review')}</section><section class="panel"><h3>Publish and preserve</h3><p>Print your exhibit, keep the progress file, and retain first-response evidence alongside corrected work.</p><div class="toolbar">${btn('print-direct','Student report','primary',`data-mode="report"`)}${btn('print-direct','Exhibit placard','',`data-mode="placard"`)}${btn('print-direct','Visitor passport','',`data-mode="visitor"`)}${btn('export','Export progress')}</div><p class="smallprint muted" style="margin-top:18px">Teacher review records are local classroom evidence, not tamper-proof certification. Pair work is not individual mastery.</p></section></div><details><summary>Checkpoint and review history</summary>${evidenceTable()}${reviewTable()}</details>`}
function evidenceTable(){return `<table><thead><tr><th>Checkpoint</th><th>Current state</th><th>Checks</th><th>First check</th><th>Help</th></tr></thead><tbody>${C.activeGroups(s).map(g=>{const a=s.attempts.filter(x=>x.group===g.id);return `<tr><td>${g.id}</td><td>${esc(C.status(s,g.id))}</td><td>${a.length}</td><td>${a.length?(a[0].passed?'Correct':'Needed revision'):'Not checked'}</td><td>${s.support.filter(h=>h.group===g.id).length}</td></tr>`}).join('')}</tbody></table>`}
function reviewTable(){return `<table><thead><tr><th>Review / track</th><th>Reviewer / status</th><th>Note</th></tr></thead><tbody>${s.reviews.map(r=>`<tr><td>${esc(r.type)} / ${r.track}</td><td>${esc(r.reviewer)} (${r.role}) — ${esc(r.status)}${r.fingerprint!==C.reviewFingerprint(s,r.type,r.track)?' · stale':''}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="3">No review recorded.</td></tr>'}</tbody></table>`}
function showHelp(gid){const g=C.getGroup(s,gid),h=C.help[g.help];s.support.push({group:gid,at:C.now()});save();openDialog('Help · '+g.title,`<dl class="answers"><dt>${esc(h[0])}</dt><dd>${esc(h[1])}</dd><dt>What to do</dt><dd>${esc(h[2])}</dd><dt>Different-number example</dt><dd>${esc(h[3])}</dd></dl>`)}
function checkGroup(id){const e=C.check(s,id);for(const k of Object.keys(errors))if(k.startsWith('field-'+id+'-'))delete errors[k];for(const [f,m]of Object.entries(e))errors[fieldId(id,f)]=C.getGroup(s,id).fields.find(x=>x.id===f).label+': '+m;save();render();if(Object.keys(e).length){$('#error-summary').focus();$('#error-summary').scrollIntoView({block:'start',behavior:'auto'})}else{toast('Work checked. Your first response and revisions are retained.');$('#group-'+id)?.scrollIntoView({block:'nearest'})}}
function proceed(){errors={};for(const g of C.activeGroups(s,s.currentStage)){if(g.type==='transfer'&&C.submissionOK(s,g.id))continue;if(!C.ok(s,g.id)){const e=C.check(s,g.id);for(const [f,m]of Object.entries(e))errors[fieldId(g.id,f)]=g.title+': '+m;}}if(Object.keys(errors).length){save();render();$('#error-summary').focus();return;}const order=[2,3,4,6,7,8];s.currentStage=order[Math.min(order.length-1,order.indexOf(s.currentStage)+1)];save();render();window.scrollTo(0,0);$('#main').focus();}
function download(obj,name){const b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCurrent(){s.handoff.exported={fingerprint:C.handoffFingerprint(s),revision:s.localRevision+1,at:C.now()};if(!save())s.handoff.exported.revision=s.localRevision;download(s,'PowersOfTen_'+(s.teamAlias.replace(/[^\w-]/g,'_')||'session')+'.json');toast('Download requested. Choose Test saved copy and reopen the file to verify it.');}
function sessions(){let records=[];try{records=db.list()}catch(e){toast(e.message)}openDialog('Saved sessions',`${s.legacy?'<p>Legacy original retained inside this migrated copy.</p>'+btn('legacy-export','Export original v0.1 save'):''}<p>Each session includes both track drafts, attempts, reviews, and learner responses. Other applications use separate storage.</p><div class="toolbar">${btn('new','New session','primary')}${btn('duplicate','Duplicate current session')}${btn('import','Import progress')}${btn('backup','Export all as backup')}</div><p class="hint">If another tab holds newer work, choose its saved session below to reload, or duplicate your current in-memory work.</p>${records.map(r=>`<div class="session-row"><div><strong>${esc(r.session?.teamAlias||'Unreadable session')}</strong><span class="smallprint">${r.error?esc(r.error):esc(C.stages[r.session.currentStage-1])+' · '+esc(r.session.updatedAt)}</span></div><div class="toolbar">${r.session?btn('resume','Resume','small',`data-id="${esc(r.id)}"`):''}${btn('delete','Delete','small danger',`data-id="${esc(r.id)}"`)}</div></div>`).join('')||'<p style="margin-top:20px">No saved sessions yet.</p>'}<div class="navbottom">${btn('clear','Clear all Powers of Ten sessions','danger')}</div>`)}
function confirmDelete(ids){openDialog('Delete saved work?',`<p><strong>${ids.length} Powers of Ten session(s)</strong> will be deleted from this browser, including both track drafts, attempts, reviews, and transfers.</p><p>This is permanent locally. Recovery requires a previously exported progress file. Downloaded files and other apps remain unchanged.</p><div class="toolbar">${btn('backup','Export all as backup')}${btn('close','Cancel')}</div>`,btn('confirm-delete','Delete '+ids.length+' session(s)','danger',`data-ids="${esc(JSON.stringify(ids))}"`))}
function importFile(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{if(!i.files[0])return;if(i.files[0].size>25*1024*1024)throw Error('File exceeds 25 MiB.');pendingImport=C.parseImport(await i.files[0].text());openDialog('Review imported progress',`<p>${pendingImport.length} valid session(s). Calculations are rechecked; imported reviews remain labeled as reported evidence.</p><ul>${pendingImport.map(x=>'<li>'+esc(x.teamAlias)+' · '+esc(C.stages[x.currentStage-1])+' · v'+esc(x.appVersion)+'</li>').join('')}</ul><p>Import as new copies preserves existing work. Replacing matching IDs requires a separate confirmation.</p><div class="toolbar">${btn('import-copies','Import as new copies','primary')}${btn('import-replace-preview','Replace matching IDs')}${btn('close','Cancel')}</div>`)}catch(e){openDialog('Import could not continue','<p>'+esc(e.message)+'</p><p>Current work has not been changed.</p>')}};i.click()}
function commitImport(replace){if(!pendingImport)return;const records=replace?pendingImport:pendingImport.map(C.duplicate);db.saveMany(records);s=records[0];pendingImport=null;$('#dialog').close();errors={};render();toast('Imported '+records.length+' session(s).')}
function teacherPanel(){teacher=true;openDialog('Teacher & inspection desk',`<p class="hint">Local classroom controls. Answers and records are not securely hidden or tamper-proof. Record an actual inspection or review; never substitute a software result for seeing the model.</p><div class="toolbar">${btn('print-direct','Teacher reference','',`data-mode="reference"`)}${btn('diagnostics','Run diagnostics')}${btn('diagnostic-export','Export diagnostics')}</div><h3 style="margin-top:25px">Record review for track ${s.track}</h3><p>Measurement truth is checked in person. The note must identify dimensions inspected and any disagreement. Amend the measurement record with a reason before accepting corrected data.</p><div class="fields"><div class="field"><label for="review-type">Review type</label><select id="review-type"><option value="inspection">Physical inspection</option><option value="interpretation">Scientific interpretation / labels</option><option value="C121">Learner 1 paper/oral transfer</option><option value="C122">Learner 2 paper/oral transfer</option></select></div><div class="field"><label for="reviewer">Reviewer alias</label><input id="reviewer" maxlength="64"></div><div class="field"><label for="review-role">Reviewer role</label><select id="review-role"><option value="teacher">Teacher</option><option value="peer">Peer (physical inspection only)</option></select></div><div class="field"><label for="review-status">Status</label><select id="review-status"><option value="pending">Pending</option><option value="accepted">Accepted</option><option value="repair-needed">Repair needed</option></select></div><div class="field wide"><label for="review-note">Actual inspection / review note (required)</label><textarea id="review-note" maxlength="400" placeholder="Name the measured quantities, values/units inspected, or reviewed interpretation. Record any mismatch."></textarea></div></div>${btn('record-review','Record review','primary')}${reviewTable()}<details><summary>Assistance / oral response / faulty checkpoint</summary><p>Oral responses can be transcribed in the corresponding response field before review. Bypass is for a faulty or inaccessible academic gate, with a recorded reason. It always produces a provisional outcome.</p><div class="fields"><div class="field"><label for="bypass-group">Checkpoint</label><select id="bypass-group">${C.activeGroups(s).map(g=>`<option value="${g.id}">${g.id} · ${esc(g.title)}</option>`).join('')}</select></div><div class="field"><label for="bypass-reviewer">Reviewer alias</label><input id="bypass-reviewer" maxlength="64"></div><div class="field wide"><label for="bypass-reason">Reason</label><textarea id="bypass-reason" maxlength="400"></textarea></div></div>${btn('bypass','Record provisional bypass','danger')}<p class="smallprint">Optional teacher rubric: math 8, representations 4, evidence/interpretation 4, usable documentation 4. Apply separately; no automatic gradebook mark.</p></details>`)}
function calculator(){openDialog('Coefficient calculator',`<p>Use this for coefficient arithmetic. You still enter and explain powers, units, and normalization.</p><div class="fields"><div class="field"><label for="calc-a">First number</label><input id="calc-a" inputmode="decimal"></div><div class="field"><label for="calc-b">Second number</label><input id="calc-b" inputmode="decimal"></div><div class="field"><label for="calc-op">Operation</label><select id="calc-op"><option>+</option><option>−</option><option>×</option><option>÷</option></select></div></div>${btn('calculate','Calculate','primary')}<p id="calc-result" role="status" style="margin-top:15px"></p>`)}
function printHeader(label,page){return `<div class="printheader">POWERS OF TEN / ${esc(label)} · ${esc(s.teamAlias||'Draft')} · ${esc(C.outcome(s))}</div><div class="printfooter">A WILLIAM MCADA PRODUCT · App ${C.VERSION} · Content ${C.CONTENT} · ${new Date().toLocaleDateString()} · Page ${page}</div>`}
function sheet(title,body,page){return `<section class="print-sheet">${printHeader(title,page)}<h1>${esc(title)}</h1>${body}</section>`}
function responseSummary(g,r){if(!r)return '';const pow=(a,n)=>esc(a||'?')+' × 10<sup>'+esc(n||'0')+'</sup>';if(g.operation){const o=g.operation;return (o.c?'Optional method: '+esc(r.c||'not submitted')+' × 10<sup>'+esc(r.e||'?')+'</sup>':'Rewrite: ('+esc(r.left||'?')+' '+o.op+' '+esc(r.right||'?')+') × 10<sup>'+esc(r.common||'?')+'</sup>')+'<br>Method evidence: '+esc(methodStatus(g.id))+'<br>Final: '+pow(r.a,r.n)+' '+esc(r.unit||'?');}if(g.type==='sci')return pow(r.a,r.n)+' m';if(g.type==='transfer'&&r.mode!=='paper')return pow(r.a,r.n)+' m = '+esc(r.decimal||'?')+' m<br>'+esc(r.direction||'?')+'; scale interpretation '+esc(r.scale||'?')+' mm';return g.fields.filter(f=>r[f.id]).map(f=>esc(f.id)+': '+esc(r[f.id])).join('; ')}
function responseTable(gs){return `<table><thead><tr><th>Task</th><th>Current response / work</th><th>First checked response</th><th>State</th></tr></thead><tbody>${gs.map(g=>{const r=C.raw(s,g.id),first=s.attempts.find(a=>a.group===g.id),response=o=>responseSummary(g,o);return `<tr><td>${g.id}<br>${esc(g.title)}</td><td>${response(r)||'Not entered'}</td><td>${first?response(first.response):'Not checked'}</td><td>${esc(C.status(s,g.id))}<br>${s.support.filter(h=>h.group===g.id).length} help opens</td></tr>`}).join('')}</tbody></table>`}
function calibration(){return `<p>Print at <strong>100%, not Fit to page</strong>. Check this line: 50 mm (acceptable 49.5–50.5 mm). If incorrect, reprint or build with a ruler.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="60mm" height="12mm" viewBox="0 0 60 12" role="img" aria-label="50 millimeter calibration line"><path d="M5 6H55M5 2V10M55 2V10" stroke="black" stroke-width="0.3" fill="none"/></svg>`}
function buildPrint(){return sheet('Science · supplied construction brief',`<p>Use prepared components. Build one model; do not calculate the scale until Mathematics.</p>${supplied()}<p>${s.track==='A'?'Keep the cell center intact, with a shallow depression: no nucleus or hole. State that paper omits three-dimensional form; thickness has no assigned scale.':'Mark the two centers 600 mm apart. Measure center to center, not edge to edge. Orbital motion and the full three-dimensional system are omitted.'}</p>${calibration()}<p>Pair / model label: ___________________________________</p><p>Actual measurement(s) + units: ______________________________</p><p>Tool / resolution: ______________________________________</p><p>Never copy a target into the observed measurement record. Use the Science passport for the class handoff.</p>`,1)}
function templates(){let pages=[];if(s.track==='A'){pages.push(sheet('Cell model guide',calibration()+`<p>160 mm diameter. Depict a shallow depression; leave the center intact. Measure your finished model.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="170mm" height="170mm" viewBox="0 0 170 170" role="img" aria-label="160 mm cell diameter guide"><circle cx="85" cy="85" r="80" fill="none" stroke="black" stroke-width=".25"/><ellipse cx="85" cy="85" rx="33" ry="21" fill="none" stroke="#888" stroke-dasharray="1 2" stroke-width=".2"/><path d="M5 85H165M85 5V165" stroke="#aaa" stroke-width=".15"/></svg>`,1))}else{pages.push(sheet('Earth and Moon size guides',calibration()+`<p>Earth diameter 20 mm; Moon target 5.5 mm. Exact Moon calculation is 5.46875 mm, rounded once for construction.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="80mm" height="35mm" viewBox="0 0 80 35" role="img" aria-label="Earth 20 mm and Moon 5.5 mm diameter templates"><g fill="none" stroke="black" stroke-width=".2"><circle cx="20" cy="18" r="10"/><circle cx="58" cy="18" r="2.75"/><path d="M18 18H22M20 16V20M56 18H60M58 16V20"/></g></svg><p>Distance strips follow: three measured 200 mm segments = 600 mm. Extra tabs join the paper and do not add distance. Align the marked endpoints exactly, then measure the assembled center-to-center distance with a ruler.</p>`,1));for(let i=0;i<3;i++)pages.push(sheet('Distance segment '+(i+1)+' of 3',`<div style="display:flex;gap:8mm;align-items:flex-start"><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="55mm" height="220mm" viewBox="0 0 55 220" role="img" aria-label="200 mm distance segment with joining tabs"><rect x="8" y="0.2" width="25" height="219.6" fill="none" stroke="#777" stroke-width=".2"/><path d="M20 10V210M10 10H30M10 210H30" stroke="black" stroke-width=".3"/><path d="M8 10H33M8 210H33" stroke="#888" stroke-width=".2" stroke-dasharray="1 1"/><text x="36" y="12" font-size="3">${i*200} mm</text><text x="36" y="211" font-size="3">${(i+1)*200} mm</text><text x="21" y="100" font-size="3" transform="rotate(90 21 100)">Segment ${i+1}: 200 mm</text></svg><div style="width:95mm"><p>200 mm measured length. Join endpoint to endpoint. Do not include the 10 mm tabs in the measured length.</p>${calibration()}<p>Assemble three segments and measure 600 mm between the two model centers. Do not measure between circle edges.</p></div></div>`,i+2))}return pages.join('').replaceAll('class="print-sheet"','class="print-sheet dimension-sheet"')}
function reference(){const data=C.objects.map(o=>`<tr><td>${esc(o[1])} — ${o[2]}</td><td>${esc(o[3])} ${esc(o[4])}</td><td>${src(o[5])}</td></tr>`).join('');return sheet('Teacher reference · notation and operations',`<p>Use exact classroom arithmetic on the rounded supplied values. Normalization is a separate requirement. No hidden significant-figure rule.</p><table><tr><th>Task</th><th>Answer / work</th></tr><tr><td>C01</td><td>8 × 10⁻⁶; 1.28 × 10⁷; 0.000000002; 384,000,000 m</td></tr><tr><td>C02</td><td>DNA &lt; specimen &lt; cell; ten times cell = 8 × 10⁻⁵ m; one decade larger.</td></tr><tr><td>C03</td><td>8 µm = 0.000008 m = 0.008 mm = 8000 nm; 1.28 × 10⁹ cm = 1.28 × 10⁷ m.</td></tr>${C.ops.map(o=>`<tr><td>${o.id}<br>${esc(o.expression)}</td><td>${o.c?`Raw coefficient ${o.c}, exponent ${o.e}. `:'Match either common exponent without changing inputs. '}Final ${o.a} × 10<sup>${o.n}</sup> ${o.unit==='widths'?'diameter-widths (dimensionless)':o.unit}.</td></tr>`).join('')}</table><p>C05a allows 8 or 8 × 10⁰; other operation finals require normalized notation. C06a equivalent 31.5 × 10⁻⁶ needs normalization. Zero is never accepted for a nonzero microscopic result.</p>`,1)+sheet('Teacher reference · models and review',`<h2>Microscopic Enlargement</h2><p>0.16 m ÷ (8 × 10⁻⁶ m) = 20,000; model:actual = 20,000:1. Target 160 mm ±2 mm. Person at scale: 34,000 m = 34 km; DNA width: 0.04 mm.</p><h2>Earth–Moon reduction</h2><p>k = 1/640,000,000 = 1.5625 × 10⁻⁹. Model:actual = 1:640,000,000. Earth 20 ±1 mm; Moon exact 5.46875 mm, construction 5.5 ±1 mm; centers 600 ±5 mm. Sun 2.1875 m; Earth–Sun distance 234.375 m.</p><h2>Common scale / transfers</h2><p>3 m ÷ 2 mm = 1500. Earth/cell = 1.6 × 10¹². One common linear scale exists mathematically but is impractical within the supplied limits.</p><p>Learner 1: 3 × 10⁻⁵ m = 0.00003 m; enlargement 5000:1; 1 mm actual → 5000 mm model. Learner 2: 6 × 10⁸ m = 600,000,000 m; reduction 1:5000; 1 mm model → 5000 mm actual.</p><h2>Review honestly</h2><p>All cell/Earth/Moon/Sun labels measure diameter; DNA measures width; Earth–Moon/Earth–Sun measure distance; light measures speed. Drawings are explanatory diagrams. Inspect a real model and record measured quantities/units, reviewer, and status. A correct report of an out-of-tolerance model is not bad arithmetic.</p><p>Featured requires all current academic checks, in-tolerance measurements, correct labels, accepted physical/interpretation reviews and required transfer review. Missing work is Draft; bypass is Provisional; known mismatch is Calibration required; pending human review is Exhibit ready for review.</p><p>Interpretations must use the selected numerical limitation and state what the model preserves/omits. Grammar and craftsmanship are not scored. Peer physical inspection is allowed; interpretation and paper/oral transfer review require a teacher record.</p>`,2)+sheet('Teacher reference · scientific sources',`<table><tr><th>Quantity / property</th><th>Teaching value</th><th>Reference</th></tr>${data}</table><p>8 µm is a chosen cell exemplar, not every cell’s diameter. Original illustrations are not observations. Microchannels, probe paths, and transfer scenarios are authored models. Data sources are optional reference links; core work runs offline.</p><p>Optional rubric (teacher-applied only): math 8, representations 4, evidence/interpretation 4, communication/documentation 4. Pair scores do not establish individual mastery.</p>`,3)}
function galleryReport(){const t=s.track,r=C.raw(s,'C11'+t),l=C.raw(s,'C10'+t),p=C.placardData(s),latest=[...s.reviews].reverse().find(x=>x.type==='interpretation'&&x.track===t);const rows=[`<h2>${esc(C.outcome(s))}</h2><p><strong>${esc(p.title||'Untitled exhibit')}</strong> · Source label ${esc(p.source||'missing')} · Scale/property labels ${C.labelsOK(s)?'consistent':'need repair'}.</p>`,responseTable([C.getGroup(s,'C10'+t)]),`<p><strong>Scientific interpretation (teacher review: ${C.reviewState(s,'interpretation')}):</strong> ${esc(r.interpretation||'Not submitted')}</p>`,`<p><strong>Other-track visit:</strong> ${esc(r.visitor||'Not submitted')} · ${esc(r.otherDirection||'direction missing')}.</p>`,`<p><strong>Property matching (${C.status(s,'C11match')}):</strong> ${responseSummary(C.getGroup(s,'C11match'),C.raw(s,'C11match'))}</p>`,responseTable([C.getGroup(s,'C121'),C.getGroup(s,'C122')]),`<p><strong>Latest interpretation reviewer:</strong> ${latest?esc(latest.reviewer)+' ('+latest.role+'), '+esc(latest.status)+'. '+esc(latest.note):'Pending'}</p><p>Help opens ${s.support.length}; bypass records ${s.teacherOverrides.length}. Complete original contexts and review histories remain in the progress export. Corrected pair work is not independent mastery.</p>`];return `<table class="gallery-report"><thead><tr><th>Gallery evidence · ${esc(s.teamAlias)} · v${C.VERSION} · continued on further pages if needed</th></tr></thead><tbody>${rows.map(x=>'<tr><td>'+x+'</td></tr>').join('')}</tbody></table>`}
function printHTML(mode){if(mode==='passport')return passport();if(mode==='blank-passport'){const old=s;s=C.newSession();s.track=old.track;const html=passport();s=old;return html;}if(mode==='science-guide')return scienceGuide();if(mode==='math-guide')return mathGuide()+reference();if(mode==='coordination')return coordination();if(mode==='templates')return templates();if(mode==='build')return buildPrint();if(mode==='placard')return sheet('Museum exhibit placard',placard(),1);if(mode==='reference')return reference();if(mode==='visitor')return sheet('Visitor passport',`<p>Visit the other model type or a teacher example.</p><p>Model examined: __________________________________</p><p>Scale ratio and enlargement/reduction: ___________________________</p><p>One quantity/property preserved: _________________________________</p><p>One feature omitted or impractical: _______________________________</p><p>Numerical evidence: _____________________________________________</p>`,1);if(mode==='transfers')return ['1','2'].map((t,i)=>sheet('Independent exit · learner '+t,`<p>Alias: ________________________ · Complete independently.</p><p>${esc(C.getGroup(s,'C12'+t).prompt)}</p><p>Normalized result: ________________________ m</p><p>Ordinary decimal: _________________________ m</p><p>Scale direction: ___________________________</p><p>${t==='1'?'1 mm actual represents how many model mm?':'1 mm model represents how many actual mm?'} __________________</p><p>Work / explanation:</p><div style="height:75mm"></div><p>Teacher receipt / review: _____________________________</p>`,i+1)).join('');
return passport()+sheet('Investigation record · notation',`<p>Team ${esc(s.teamAlias)} · Learners ${s.students.map(esc).join(' / ')}. Track ${s.track}. ${s.imported?'Imported evidence; not newly observed.':''}</p>${responseTable(C.activeGroups(s,2))}`,1)+sheet('Scientific calculations',`<p>All eight operations apply to both tracks. Current and first checked responses are retained separately.</p>${responseTable(C.activeGroups(s,3))}`,2)+sheet('Physical exhibit · plan and measurement',`<p>${s.track==='A'?'Microscopic Enlargement':'Earth–Moon Desktop Model'} · Original explanatory diagram, not physical measurement.</p><div class="art-preview">${A.track(s.track)}</div>${responseTable(C.activeGroups(s,4))}${measurementTable()}${responseTable([C.getGroup(s,'C13'+s.track)])}<p>Tool: ${esc(C.raw(s,'C09'+s.track).tool)}. Resolution/estimate: ${esc(C.raw(s,'C09'+s.track).resolution)} mm. Physical fit: ${C.fit(s)?'Within tolerance (self-report)':'Needs checking/repair'}. Inspection: ${C.reviewState(s,'inspection')}.</p><p>Inspector / note: ${(()=>{const r=[...s.reviews].reverse().find(x=>x.type==='inspection'&&x.track===s.track);return r?esc(r.reviewer)+' ('+r.role+') — '+esc(r.note):'Pending'})()}</p><p>Exact calculation and construction targets remain separate; distance is center to center.</p>`,3)+sheet('Gallery, transfer, and museum outcome',galleryReport(),4)}
function printMenu(mode='report'){printMode=mode;openDialog('Print studio',`<p>Choose one output. Student views exclude the teacher reference. Use A4 or Letter, portrait, 100% scale; turn off browser headers/footers.</p><div class="toolbar">${[['passport','Science passport'],['blank-passport','Blank passport'],['report','Student report'],['build','Build sheet'],['templates','Dimensional templates'],['placard','Exhibit placard'],['visitor','Visitor passport'],['transfers','Exit slips'],...(teacher?[['reference','Teacher reference']]:[])].map(([m,l])=>btn('preview-print',l,m===mode?'primary':'',`data-mode="${m}"`)).join('')}</div><div id="print-preview">${printHTML(mode)}</div>`,btn('print-now','Print / Save PDF','primary'))}

function methodStatus(id){const e=C.methodErrors(s,id);return e===null?'Not submitted':Object.keys(e).length?'Needs revision: '+Object.values(e).join(' '):'Submitted method checked';}
function dashboard(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">One model · two subjects</p><h1>Too small.<br>Too far.<br><em>Make it real.</em></h1><p>How can we represent something too small or too large to experience directly—and how trustworthy is our model?</p></div><div class="hero-art">${A.hero()}</div></section><div class="cards"><section class="panel"><p class="eyebrow">Day 1 · Science · 40 minutes</p><h2>Build. Observe. Save.</h2><p>Build one model, measure it honestly, and leave with a Science Evidence Passport and a portable progress file.</p>${btn('lesson','Start / continue Science','primary',`data-lesson="science"`)}</section><section class="panel"><p class="eyebrow">Day 2 · Mathematics · target 40 minutes</p><h2>Calculate. Compare. Explain.</h2><p>Use yesterday’s measurements to calculate scientific notation, intended scale, observed scale, and signed deviations.</p><div class="toolbar">${btn('lesson','Continue on this device','primary',`data-lesson="math"`)}${btn('import','Import Science progress')}${btn('paper','Use my paper passport')}</div></section></div><section class="panel"><h3>My evidence</h3>${statusSummary()}<p>QR links open this project; they do not transfer your saved answers. Use aliases. Your teacher chooses a working file-transfer route before Science begins.</p>${btn('evidence','Evidence and exports')}${btn('guides','Teacher guides')}</section>`;}
function statusSummary(){return `<ul><li>Science record: ${Object.keys(C.scienceErrors(s)).length?'incomplete':'ready for mathematics (not teacher approval)'}</li><li>Saved copy: ${s.handoff.verified?.fingerprint===C.handoffFingerprint(s)?'reopened and matched at '+esc(s.handoff.verified.at):'not verified for this evidence'}</li><li>Reported physical fit: ${C.fit(s)?'within tolerance':'outside tolerance or incomplete'}</li><li>Human inspection: ${esc(C.reviewState(s,'inspection'))}; interpretation: ${esc(C.reviewState(s,'interpretation'))}</li><li>Mathematics: ${countDone().join(' / ')} checkpoints; final outcome: ${esc(C.outcome(s))}</li></ul>`;}
function supplied(){return `<div class="factbox"><strong>Supplied references and targets — not observations</strong><p>${s.track==='A'?'Red blood cell exemplar: diameter 8 µm (0.008 mm), R2. Model target: 160 mm diameter.':'Earth diameter 1.28 × 10⁷ m, Moon diameter 3.5 × 10⁶ m, mean center distance 3.84 × 10⁸ m (R3/R4). Construction targets: Earth 20 mm, Moon 5.5 mm, centers 600 mm apart.'}</p><p>${(s.track==='A'?['R2']:['R3','R4']).map(src).join(' · ')}</p><p>These are rounded teaching values. App pictures are explanatory diagrams, not new observations.</p></div>`;}
function scienceField(k,label,options=null){const v=s.science[s.track][k],n=C.scienceLimits[k],id='science-'+k;return `<div class="field"><label for="${id}">${label} (max ${n} characters)</label>${options?`<select id="${id}" data-science="${k}"><option value="">Choose…</option>${options.map(([x,l])=>`<option value="${x}" ${v===x?'selected':''}>${l}</option>`).join('')}</select>`:`<textarea id="${id}" data-science="${k}" maxlength="${n}">${esc(v)}</textarea>`}</div>`;}
function scienceDay(){const step=s.scienceStep,a=s.science[s.track];return `<div class="sectiontop"><h2>Science Day · ${['Brief','Build','Observe','Passport'][step-1]}</h2><span class="badge">40-minute lesson</span></div><nav class="toolbar" aria-label="Science tasks">${['Brief · 0–8 min','Build · 8–22 min','Observe · 22–34 min','Passport · 34–40 min'].map((label,i)=>btn('science-step',label,step===i+1?'primary':'',`data-step="${i+1}"`)).join('')}</nav>${a.route==='paper'?'<p class="hint">Paper recovery: transcribe the passport. Confirm the build and measurement record from that paper; you do not need to rebuild. Human reviews remain pending.</p>':a.route==='legacy'?'<p class="hint">Migrated copy: original answers and history are retained. Complete the new Science fields; old approvals remain historical.</p>':''}${step===1?scienceBrief():step===2?construction():step===3?scienceObserve():finishScience()}${step<4?`<div class="navbottom">${btn('science-step','Continue →','primary',`data-step="${step+1}"`)}</div>`:''}`;}
function scienceBrief(){return `<section class="panel"><p class="eyebrow">Museum story</p><h3>Make the invisible understandable</h3><p>A museum needs a model visitors can trust. Choose a cell or the Earth–Moon system. Later, mathematics will test how closely the model represents the supplied dimensions.</p></section><section class="panel"><p class="eyebrow">Your directions · 0–8 minutes</p><p>Use aliases, confirm one track, identify its property/source, and predict one feature your model will preserve. Work as Builder and Verifier; swap at minute 15.</p><div class="fields">${[['teamAlias','Team alias',s.teamAlias],['student1','Learner 1 alias',s.students[0]],['student2','Learner 2 alias',s.students[1]]].map(([k,l,v])=>`<div class="field"><label for="meta-${k}">${l}</label><input id="meta-${k}" data-meta="${k}" maxlength="64" value="${esc(v)}"></div>`).join('')}</div><div class="track-options">${['A','B'].map(t=>`<button class="track-option" data-action="track" data-track="${t}" aria-pressed="${s.track===t}">${A.track(t)}<h3>${t==='A'?'Cell model':'Earth–Moon model'}</h3></button>`).join('')}</div>${supplied()}<div class="fields">${scienceField('label','Short label to attach to your model')}${scienceField('property','Property represented',[['diameter','Cell diameter'],['diameter-distance','Earth/Moon diameters and center distance']])}${scienceField('source','Supplied source',[['R2','R2 · Histology Guide'],['R3/R4','R3/R4 · NASA Earth and Moon']])}${scienceField('prediction','I predict the model will preserve…')}</div></section>`;}
function scienceObserve(){const g=C.getGroup(s,'C09'+s.track);return `<section class="panel"><p class="eyebrow">Directions · 22–34 minutes</p><h3>Measure what you made</h3><p>Enter actual measurements, not the targets. A mismatch is useful evidence. No scale or deviation calculation is needed today. Tool name: maximum 60 characters.</p>${supplied()}<div class="fields">${g.fields.filter(f=>!f.id.endsWith('Deviation')).map(f=>inputHTML(g,f).replace('maxlength="600"','maxlength="60"')).join('')}</div>${btn('confirm-measurements','These measurements belong to this build','primary')}<p>${s.science[s.track].measuredBuild===s.buildRevisions[s.track]?'Measurements linked to build revision '+s.buildRevisions[s.track]:'Confirm after measuring the current build.'}</p></section><section class="panel"><h3>Interpret the science</h3><p>Ask another pair to check one dimension if time permits; otherwise record “not checked.” Inspect the teacher’s other-track example.</p><div class="fields">${scienceField('preserved','One feature preserved is…')}${scienceField('omitted','One feature omitted or distorted is…')}${scienceField('other','The other-track model preserves / omits…')}${scienceField('peer','Peer check: alias, dimension and disagreement, or “not checked”')}</div><p>Cell: describe a biconcave disc with an intact center. A flat model omits 3D shape. Earth–Moon: distinguish center distance from the gap between edges.</p></section>`;}
function passportSummary(){const r=C.raw(s,'C09'+s.track);return `<p><strong>Model ${esc(s.science[s.track].label||'not labeled')}</strong> · Track ${s.track} · ${esc(s.science[s.track].route)} evidence</p><table><thead><tr><th>Quantity</th><th>Supplied target</th><th>Observed</th></tr></thead><tbody>${C.measurements[s.track].map(([id,label,target])=>`<tr><td>${label}</td><td>${target} mm</td><td>${esc(r[id]||'—')} ${esc(r[id+'Unit'])}</td></tr>`).join('')}</tbody></table><p>Tool: ${esc(r.tool||'—')}; resolution/estimate ${esc(r.resolution||'—')} mm.</p>`;}
function passport(){const a=s.science[s.track],e=C.scienceErrors(s);return `<section class="print-sheet passport"><div class="printheader">POWERS OF TEN · SCIENCE EVIDENCE PASSPORT · v${C.VERSION}</div><h1>One model. Evidence for tomorrow.</h1><p><strong>Pair:</strong> ${esc(s.teamAlias||'________________')} · ${s.students.map(x=>esc(x||'________')).join(' / ')}<br><strong>Model label:</strong> ${esc(a.label||'________________')} · Track ${s.track} · build ${s.buildRevisions[s.track]}</p>${supplied()}${passportSummary()}<dl>${[['property','Property'],['source','Source IDs'],['prediction','Prediction'],['preserved','Preserved feature'],['omitted','Omitted/distorted feature'],['other','Other-track observation'],['peer','Peer check']].map(([k,l])=>`<dt>${l}</dt><dd>${esc(a[k]||'________________________________________________')}</dd>`).join('')}</dl><p><strong>Next class:</strong> What scale did we intend, and what scale did we actually produce?</p><p><strong>Science status:</strong> ${Object.keys(e).length?'Incomplete record':'Ready for mathematics — interpretation not automatically approved'}. Physical build: ${s.built[s.track]?'confirmed by pair':'not confirmed'}. Human inspection: ${esc(C.reviewState(s,'inspection'))}.</p><p class="smallprint">Session ${esc(s.sessionId)} · revision ${s.localRevision}<br>Updated ${esc(s.updatedAt)} · export requested ${esc(s.handoff.exported?.at||'not yet')}<br>Source route: ${esc(a.route)}. A WILLIAM MCADA PRODUCT.</p></section>`;}
function finishScience(){const missing=C.scienceErrors(s);return `<section class="panel"><p class="eyebrow">Directions · 34–40 minutes</p><h3>Finish Science Day</h3><p>Label and pack the model. Save, download progress, then use Test saved copy to reopen that exact file. Print/save the passport as PDF or copy it onto the teacher’s preprinted passport. Collect model and passport together.</p>${Object.keys(missing).length?'<div class="hint"><strong>Still needed</strong><ul>'+Object.values(missing).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':'<p class="result">Science evidence ready for Mathematics. Arithmetic and human review are separate.</p>'}<div class="toolbar">${btn('save','Save')}${btn('export','Download progress','primary')}${btn('test-copy','Test saved copy')}${btn('print-direct','Print / Save passport PDF','',`data-mode="passport"`)}${btn('lesson','Continue to Mathematics','',`data-lesson="math"`)}</div>${statusSummary()}<p>No download success is assumed. If file transfer fails, keep this page open and complete the paper passport. Export incomplete work honestly if time runs out.</p></section><div id="passport-preview">${passport()}</div>`;}
function testCopy(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{if(!i.files[0])return;if(i.files[0].size>5*1024*1024)throw Error('Choose one session file, at most 5 MiB.');const candidates=C.parseImport(await i.files[0].text());if(candidates.length!==1)throw Error('Choose the single-session Science export.');C.verifyCopy(s,candidates[0]);save();render();openDialog('Saved copy matched','<p>The file was reopened and its session, export revision and Science handoff fields match. Your active answers were not replaced. Keep this file for Mathematics.</p>'+passportSummary());}catch(e){openDialog('Saved copy did not match','<p>'+esc(e.message)+'</p><p>Your current work is unchanged.</p>');}};i.click();}
function scienceGuide(){return sheet('Science teacher guide · 40 minutes',`<p><strong>Purpose:</strong> construct a representation, measure honestly, and distinguish supplied references, observations and scientific claims.</p><h2>Before class</h2><p>Prepare card/discs, tape, millimeter rulers, labels and a 600 mm workspace for cosmic pairs; reusable material is optional for cells. Supply a teacher model of the other track. Preprint one blank passport per pair. Calibrate printed templates: 50 mm line within 0.5 mm. Test site and the chosen iPad Files transfer route. Scientific notation and ratio prerequisites belong before these lessons.</p><table><tr><th>Minutes</th><th>Directions / evidence</th></tr><tr><td>0–4</td><td>Brief, source/model distinction, prediction.</td></tr><tr><td>4–8</td><td>One track; pair aliases, source/property and model label. Assign Builder/Verifier.</td></tr><tr><td>8–22</td><td>Build from supplied dimensions; swap at minute 15. Prepared components, no decoration requirement.</td></tr><tr><td>22–29</td><td>Measure actual dimensions; tool/resolution. Peer check if possible.</td></tr><tr><td>29–34</td><td>Preserved/omitted feature and other-track observation.</td></tr><tr><td>34–40</td><td>Pack, passport, export and reopen file. Collect labeled models and passports.</td></tr></table><h2>Prompts and misconceptions</h2><p>“What did we observe? What was supplied?” A cell is a biconcave disc, not a hole; paper omits 3D form. Scale applies to diameter, not thickness. Cosmic distance is center to center; orbit/motion is omitted. Screen diagrams are not measurements.</p><h2>Accessible alternatives and finish</h2><p>Use prepared components, a scribe or teacher-transcribed oral claims. Reserve the last six minutes. Rough/out-of-tolerance models can complete Science. Never invent ideal measurements. If incomplete, export an honest draft and record that the timing goal was not met. Paper passport is the fallback; reviews stay separate. Classroom timing, physical iPads and printer calibration require local trials.</p>`,1);}
function mathGuide(){return sheet('Mathematics teacher guide · target 40 minutes',`<p><strong>Purpose:</strong> apply notation, units and all four operations, then audit the Science model with exact scale and deviation calculations.</p><p><strong>Prepare:</strong> same pairs, labeled models, passports and tested progress files. Prerequisites: signed exponent rules, metric conversion, ratios and ruler use. Open Mathematics via Continue, Import, or paper recovery. Paper recovery transcribes Science evidence, not approval.</p><table><tr><th>Minutes</th><th>Work / evidence</th></tr><tr><td>0–3</td><td>Resume/import and match model label; paper recovery if needed.</td></tr><tr><td>3–7</td><td>C01–03 notation, magnitude and units.</td></tr><tr><td>7–23</td><td>Eight C04–07 tasks, both scale ranges. Alternate Calculator/Checker each task; optional method scaffolding.</td></tr><tr><td>23–31</td><td>C08 intended scale; C09 deviations; C13 observed factors from Science measurements.</td></tr><tr><td>31–36</td><td>C10 limitations/shared scale; C11 scientific interpretation, labels.</td></tr><tr><td>36–40</td><td>C12 separate exits; final export/report.</td></tr></table><p><strong>Observed-factor keys:</strong> cell 159 mm → 19,875; Earth 20 mm → 1/640000000; Moon 5.5 mm → 11/7000000000; centers 598 mm → 299/192000000000. Fractions and equivalent model:actual ratios accepted. Cell deviation −1 mm; center deviation −2 mm.</p><p>Moon exact target 5.46875 mm rounds to 5.5 mm; inferred ratios need not be identical. Tolerances: cell ±2, Earth ±1, Moon ±1, centers ±5 mm, endpoints included. Academic calculations remain exact. A correct report of a poor fit is valid mathematics.</p><p>Final answers are required; submitted methods are checked separately and retained. Use oral transcription, printed independent exits or a scribe as needed. Do not infer independent mastery from pair work or auto-checks. Answer key follows. The second-day workload is a pilot timing target.</p>`,1);}
function coordination(){return sheet('Science + Mathematics · coordination',`<p>Class / date: _____________________________</p><p>Science teacher: _________________________</p><p>Mathematics teacher / next meeting: _________________________</p><p>Pair aliases / continuity list location: _________________________</p><p>Labeled model storage / transport: _________________________</p><p>Passport collection / return location: _________________________</p><p>Chosen file-transfer route, tested on class iPads: _________________________</p><p>Paper fallback / printer availability: _________________________</p><p>Materials ready, other-track example, 50 mm calibration checked: ____________</p><p>Prerequisites already taught: scientific notation; signed exponent rules; all four operations; metric conversion; model:actual ratios; ruler reading.</p><p>At minute 34: pack, save, export, reopen saved copy, collect model + passport. At Mathematics start: return matching model/passport and resume/import. QR opens the app, not private progress.</p><p>Record actual Day 1 finish time / pairs incomplete: _________________________</p><p>School network, Files import/export and physical camera QR checked: __________</p><p>Science completeness, saved-copy verification, mathematics, physical fit and human review must stay separate.</p>`,1);}
function subjectAction(a,b){if(a==='lesson'){s.lesson=b.dataset.lesson;if(s.lesson==='math'&&![2,3,4,6,7,8].includes(s.currentStage))s.currentStage=2;save();render();}
else if(a==='science-step'){s.scienceStep=Number(b.dataset.step);save();render();}
else if(a==='math-stage'){s.currentStage=Number(b.dataset.stage);save();render();}
else if(a==='evidence'){s.lesson='science';s.scienceStep=4;save();render();}
else if(a==='confirm-measurements'){s.science[s.track].measuredBuild=s.buildRevisions[s.track];save();render();}
else if(a==='test-copy')testCopy();
else if(a==='paper'){if(!save())throw Error('Export current work before starting paper recovery.');s=C.newSession();s.science.A.route=s.science.B.route='paper';s.lesson='science';render();toast('Copy your paper passport into Brief and Observe; confirm the recorded physical build.');}
else if(a==='legacy-export'){download(s.legacy,'PowersOfTen_original_v0.1.json');}
else if(a==='guides'){teacher=true;openDialog('Two subjects · teacher guides',`<p>Prepare before the 40-minute Science clock starts. Timing and physical-device checks require a classroom trial.</p><div class="toolbar">${[['science-guide','Science · 40 minutes'],['math-guide','Mathematics + answer key'],['coordination','Coordination sheet'],['blank-passport','Blank passport']].map(([m,l])=>btn('print-direct',l,'',`data-mode="${m}"`)).join('')}${btn('teacher','Reviews and assistance')}</div>`);}
else return false;return true;}

$('#app').addEventListener('input',onInput);$('#dialog').addEventListener('input',onInput);
function onInput(e){const el=e.target;if(el.dataset.science){s.science[s.track][el.dataset.science]=el.value;}else if(el.dataset.input){try{C.setInput(s,el.dataset.input,el.value);const gid=el.dataset.input.split('.')[0],pr=$('#preview-'+gid),r=C.getGroup(s,gid)?C.raw(s,gid):null;if(pr&&r)pr.innerHTML=esc(r.a)+' × 10<sup>'+esc(r.n)+'</sup>'}catch(err){toast(err.message)}}else if(el.dataset.meta){const k=el.dataset.meta;if(k==='teamAlias')s.teamAlias=el.value;if(k==='student1'||k==='student2')s.students[k==='student1'?0:1]=el.value;if(k==='built')s.built[s.track]=el.checked;if(k==='planner'||k==='builder')s.roles[k]=el.value;}}
document.addEventListener('change',e=>{if(e.target.dataset.input||e.target.dataset.meta||e.target.dataset.science){save();if(e.target.dataset.input?.endsWith('.mode'))render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;if(subjectAction(a,b))return; if(a==='close'){$('#dialog').close();return}if(a==='save'){save();toast(saveMessage)}else if(a==='help')showHelp(b.dataset.group);else if(a==='check')checkGroup(b.dataset.group);else if(a==='next')proceed();else if(a==='back'){s.currentStage=Math.max(1,s.currentStage-1);errors={};save();render();window.scrollTo(0,0)}else if(a==='stage'){const n=Number(b.dataset.stage),m=C.missing(s,n);if(m.length&&n>s.currentStage){toast('First finish: '+m.join(', '));return}s.currentStage=n;errors={};save();render();window.scrollTo(0,0)}else if(a==='track'){s.track=b.dataset.track;errors={};save();render();toast('Track selected. The other draft and all operation evidence are retained.')}else if(a==='learner'){learner=b.dataset.learner;errors={};render();$('#group-C12'+learner)?.scrollIntoView({block:'center'})}else if(a==='minus'){const el=$('#'+b.dataset.target);el.value=el.value.startsWith('-')?el.value.slice(1):'-'+el.value;el.dispatchEvent(new Event('input',{bubbles:true}));save();el.focus()}else if(a==='rebuild'){if(s.buildRevisions[s.track]>=100)throw Error('Build revision limit reached. Export and start a new session.');s.buildRevisions[s.track]++;s.built[s.track]=false;s.science[s.track].measuredBuild=-1;save();render();toast('Rebuild recorded. Previous measurements retained; recheck after construction.')}else if(a==='export')exportCurrent();else if(a==='sessions')sessions();else if(a==='new'){if(!save()){openDialog('Preserve this work first','<p>The current session could not be saved. Export current progress before starting another session.</p><div class="toolbar">'+btn('export','Export progress')+btn('new-confirm','Start new session','danger')+btn('close','Cancel')+'</div>');return}s=C.newSession();errors={};$('#dialog').close();render()}else if(a==='new-confirm'){s=C.newSession();errors={};$('#dialog').close();render()}else if(a==='duplicate'){s=C.duplicate(s);save();$('#dialog').close();render()}else if(a==='resume'){const v=db.read(b.dataset.id);if(!v)throw Error('Session no longer exists.');s=v;errors={};$('#dialog').close();render()}else if(a==='backup'){const rows=db.list();if(rows.some(r=>r.error))throw Error('A saved record is unreadable. Export current work; recover unreadable data before clearing it.');download(C.bundle(rows.map(r=>r.session)),'PowersOfTen_all_sessions_backup.json');toast('Backup download requested.')}else if(a==='delete')confirmDelete([b.dataset.id]);else if(a==='clear')confirmDelete(db.ids());else if(a==='confirm-delete'){const ids=JSON.parse(b.dataset.ids);db.remove(ids);if(ids.includes(s.sessionId))s=C.newSession();$('#dialog').close();errors={};saveMessage='Deletion completed';render();toast('Deleted '+ids.length+' session(s).')}else if(a==='import')importFile();else if(a==='import-copies')commitImport(false);else if(a==='import-replace-preview')openDialog('Replace matching saved sessions?',`<p>This will replace records with the imported IDs: ${pendingImport.map(x=>esc(x.teamAlias)).join(', ')}. All other sessions remain.</p><p>Export a backup first. Cancellation keeps current work.</p><div class="toolbar">${btn('backup','Export current backup')}${btn('import-replace','Confirm replacement','danger')}${btn('close','Cancel')}</div>`);else if(a==='import-replace')commitImport(true);else if(a==='teacher')teacherPanel();else if(a==='record-review'){C.review(s,$('#review-type').value,$('#reviewer').value,$('#review-role').value,$('#review-status').value,$('#review-note').value);save();render();teacherPanel();toast('Review recorded for the current evidence.')}else if(a==='bypass'){C.bypass(s,$('#bypass-group').value,$('#bypass-reviewer').value,$('#bypass-reason').value);save();render();teacherPanel();toast('Provisional bypass recorded.')}else if(a==='diagnostics')openDialog('Built-in diagnostics','<ul>'+C.diagnostics().map(x=>'<li>'+esc(x.name)+': '+(x.passed?'Passed':'FAILED')+'</li>').join('')+'</ul><p>Reference arithmetic only. This does not test a physical model, printer, or device.</p>');else if(a==='diagnostic-export')download({project:'powers-of-ten',app:C.VERSION,content:C.CONTENT,at:C.now(),storageAvailable:db.available,checks:C.diagnostics()},'PowersOfTen_diagnostics.json');else if(a==='calculator')calculator();else if(a==='calculate'){const x=C.q($('#calc-a').value),y=C.q($('#calc-b').value),op=$('#calc-op').value,z=op==='+'?x.add(y):op==='−'?x.sub(y):op==='×'?x.mul(y):x.div(y);$('#calc-result').textContent='Exact result: '+z.str()+' · decimal display: '+z.num();}else if(a==='print-menu')printMenu();else if(a==='print-direct'||a==='preview-print'){if(b.dataset.mode==='reference'&&!teacher)return;printMenu(b.dataset.mode)}else if(a==='print-now'){$('#print-root').innerHTML=printHTML(printMode);$('#dialog').close();window.print();}}catch(err){toast(err.message);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('storage',e=>{if(e.key===C.PREFIX+'session:'+s.sessionId){saveMessage='Saved work changed in another tab. Open Sessions to reload or duplicate.';$('#save-status')&&($('#save-status').textContent=saveMessage)}});
window.addEventListener('beforeunload',e=>{if(!db.available){e.preventDefault();e.returnValue='Export progress before leaving.'}});
window.SNApp={get state(){return s},setState(v){s=C.validateSession(v,false);errors={};render()},render,printHTML,store:db};render();
})();
